	s = evFrun(t, pr, d, words, 16, w, 5, EkGlyphs(), s)
	s = evFint(t, pr, d, words, 16, w, 9, EkLine(), -1, s)
	s = evFbits(t, pr, d, words, 16, w, 10, 1, s)
	s = evFint(t, pr, d, words, 16, w, 11, EkConf(), -1, s)
